class VectorMemory:
    def __init__(self):
        self.pinecone_client = Pinecone(api_key=os.getenv('PINECONE_API_KEY'))
        self.embedding_model = SentenceTransformer('all-MiniLM-L6-v2')

        try:
            self.index = self.pinecone_client.Index('cognitive-memory')
        except:
            self.pinecone_client.create_index(
                name='cognitive-memory',
                dimension=384,
                metric='cosine',
                spec=ServerlessSpec(cloud='aws', region='us-east-1')
            )
            time.sleep(60)
            self.index = self.pinecone_client.Index('cognitive-memory')

    def store_insight(self, content: str, metadata: Dict):
        vector_id = hashlib.sha256(f"{content}{time.time()}".encode()).hexdigest()
        embedding = self.embedding_model.encode(content).tolist()

        self.index.upsert(vectors=[{
            'id': vector_id,
            'values': embedding,
            'metadata': {
                **metadata,
                'content': content[:1000],
                'timestamp': time.time()
            }
        }])

        return vector_id

    def recall_similar(self, query: str, top_k: int = 20) -> List[Dict]:
        query_embedding = self.embedding_model.encode(query).tolist()
        results = self.index.query(vector=query_embedding, top_k=top_k, include_metadata=True)

        recalled = []
        for match in results.matches:
            recalled.append({
                'content': match.metadata.get('content', ''),
                'score': match.score,
                'metadata': match.metadata
            })

        return recalled

class PlannerModule:
    def __init__(self, cerebras_client: Cerebras, xai_client: OpenAI):
        self.cerebras = cerebras_client
        self.xai = xai_client

    def create_research_plan(self, query: str, context: List[Dict]) -> Dict:
        context_text = "\n".join([f"- {item['content'][:500]}" for item in context[:10]])

        planning_prompt = f"""You are a strategic research planner. Create a comprehensive, adaptive research plan.

Query: {query}

Previous knowledge from memory:
{context_text}

Create a detailed research plan with:
1. Primary research objectives (3-5 specific goals)
2. Search strategies (multiple angles to explore)
3. Key questions to answer
4. Expected challenges and how to overcome them
5. Success criteria
6. Contingency plans if initial approaches fail

Return as JSON:
{{
    "objectives": ["obj1", "obj2", ...],
    "search_strategies": [
        {{"strategy": "...", "rationale": "...", "priority": 1-5}}
    ],
    "key_questions": ["q1", "q2", ...],
    "challenges": [
        {{"challenge": "...", "mitigation": "..."}}
    ],
    "success_criteria": ["criterion1", ...],
    "contingencies": [
        {{"if": "condition", "then": "action"}}
    ]
}}"""

        try:
            response = self.cerebras.chat.completions.create(
                model="qwen-3-235b-a22b-thinking-2507",
                messages=[{"role": "user", "content": planning_prompt}],
                max_tokens=32768,
                temperature=0.8
            )

            plan_text = response.choices[0].message.content

            try:
                plan = json.loads(plan_text)
            except:
                plan = {
                    "objectives": ["Comprehensive research on the query"],
                    "search_strategies": [{"strategy": "Multi-angle search", "rationale": "Coverage", "priority": 5}],
                    "key_questions": [query],
                    "challenges": [],
                    "success_criteria": ["Thorough report"],
                    "contingencies": []
                }

            return plan

        except Exception as e:
            return {
                "objectives": [query],
                "search_strategies": [{"strategy": "Comprehensive search", "rationale": "Default", "priority": 5}],
                "key_questions": [query],
                "challenges": [],
                "success_criteria": [],
                "contingencies": [],
                "error": str(e)
            }

    def replan(self, original_plan: Dict, execution_results: Dict, iteration: int) -> Dict:
        replan_prompt = f"""You are replanning research strategy based on execution results.

Original plan objectives: {json.dumps(original_plan.get('objectives', []))}

Execution iteration: {iteration}
Results summary: {json.dumps(execution_results, indent=2)[:5000]}

Analyze what's working and what's not. Create an updated plan that:
1. Doubles down on successful strategies
2. Abandons unproductive approaches
3. Explores new angles based on findings
4. Adjusts priorities based on results

Return updated plan as JSON with same structure as original."""

        try:
            response = self.xai.chat.completions.create(
                model="grok-4-fast",
                messages=[{"role": "user", "content": replan_prompt}],
                max_tokens=32768,
                temperature=0.7
            )

            updated_plan = json.loads(response.choices[0].message.content)
            return updated_plan
        except:
            return original_plan

class CriticModule:
    def __init__(self, bedrock_client, cerebras_client: Cerebras):
        self.bedrock = bedrock_client
        self.cerebras = cerebras_client

    def critique_findings(self, findings: str, sources: List[Dict]) -> Dict:
        sources_summary = "\n".join([f"[{i+1}] {s.get('title', 'Untitled')}: {s.get('url', '')}" for i, s in enumerate(sources[:30])])

        critique_prompt = f"""You are a critical analyst. Your job is to find flaws, biases, gaps, and logical errors.

Findings to critique:
{findings[:20000]}

Sources used:
{sources_summary}

Provide critical analysis:
1. Logical fallacies or weak reasoning
2. Missing evidence or unsupported claims
3. Potential biases in sources
4. Contradictions or inconsistencies
5. Important questions left unanswered
6. Alternative interpretations
7. Quality and credibility of sources

Return as JSON:
{{
    "logical_issues": ["issue1", ...],
    "missing_evidence": ["gap1", ...],
    "biases": ["bias1", ...],
    "contradictions": ["contradiction1", ...],
    "unanswered_questions": ["q1", ...],
    "alternative_views": ["view1", ...],
    "source_quality_issues": ["issue1", ...],
    "overall_confidence": 0-100,
    "recommendations": ["rec1", ...]
}}"""

        try:
            body = json.dumps({
                "anthropic_version": "bedrock-2023-05-31",
                "max_tokens": 200000,
                "messages": [{"role": "user", "content": critique_prompt}],
                "temperature": 0.7
            })

            response = self.bedrock.invoke_model(
                modelId="anthropic.claude-sonnet-4-5-v2:0",
                body=body
            )

            response_body = json.loads(response['body'].read())
            critique_text = response_body['content'][0]['text']

            try:
                critique = json.loads(critique_text)
            except:
                critique = {
                    "logical_issues": [],
                    "missing_evidence": [],
                    "biases": [],
                    "contradictions": [],
                    "unanswered_questions": [],
                    "alternative_views": [],
                    "source_quality_issues": [],
                    "overall_confidence": 50,
                    "recommendations": []
                }

            return critique

        except Exception as e:
            return {
                "error": str(e),
                "overall_confidence": 50,
                "recommendations": ["Manual review recommended"]
            }

    def defend_or_revise(self, findings: str, critique: Dict) -> Dict:
        defense_prompt = f"""You are defending or revising findings based on critical feedback.

Original findings:
{findings[:15000]}

Critical feedback:
{json.dumps(critique, indent=2)}

For each criticism:
1. Either defend the original finding with stronger evidence
2. Or revise the finding to address the criticism

Return as JSON:
{{
    "defended": [
        {{"criticism": "...", "defense": "...", "evidence": "..."}}
    ],
    "revised": [
        {{"original": "...", "criticism": "...", "revision": "..."}}
    ],
    "acknowledged_gaps": ["gap1", ...],
    "new_research_needed": ["area1", ...]
}}"""

        try:
            response = self.cerebras.chat.completions.create(
                model="gpt-oss-120b",
                messages=[{"role": "user", "content": defense_prompt}],
                max_tokens=32768,
                temperature=0.6
            )

            defense = json.loads(response.choices[0].message.content)
            return defense
        except:
            return {
                "defended": [],
                "revised": [],
                "acknowledged_gaps": [],
                "new_research_needed": []
            }

class MultiAgentCoordinator:
    def __init__(self, exa: Exa, cerebras: Cerebras, xai: OpenAI, bedrock):
        self.exa = exa
        self.cerebras = cerebras
        self.xai = xai
        self.bedrock = bedrock

    def librarian_agent(self, query: str, constraints: Dict) -> Dict:
        try:
            search_types = ['neural', 'keyword', 'auto']
            all_results = []

            for search_type in search_types:
                result = self.exa.search_and_contents(
                    query=query,
                    type=search_type,
                    num_results=100,
                    text=True,
                    highlights=True,
                    livecrawl="preferred",
                    **constraints
                )

                all_results.extend([{
                    'url': r.url,
                    'title': getattr(r, 'title', ''),
                    'text': getattr(r, 'text', ''),
                    'highlights': getattr(r, 'highlights', []),
                    'search_type': search_type
                } for r in result.results])

            return {'agent': 'librarian', 'results': all_results, 'count': len(all_results)}
        except Exception as e:
            return {'agent': 'librarian', 'results': [], 'error': str(e)}

    def data_analyst_agent(self, sources: List[Dict]) -> Dict:
        analysis_prompt = f"""You are a data analyst. Extract quantitative insights, statistics, trends from these sources.

Sources:
{json.dumps([{'title': s.get('title', ''), 'text': s.get('text', '')[:2000]} for s in sources[:50]], indent=2)[:30000]}

Return structured analysis as JSON:
{{
    "statistics": [
        {{"metric": "...", "value": "...", "source": "...", "confidence": 0-100}}
    ],
    "trends": [
        {{"trend": "...", "direction": "up/down/stable", "evidence": "..."}}
    ],
    "correlations": [
        {{"factor1": "...", "factor2": "...", "relationship": "..."}}
    ],
    "data_quality": {{
        "completeness": 0-100,
        "reliability": 0-100,
        "recency": "current/dated/mixed"
    }}
}}"""

        try:
            response = self.cerebras.chat.completions.create(
                model="gpt-oss-120b",
                messages=[{"role": "user", "content": analysis_prompt}],
                max_tokens=32768,
                temperature=0.5
            )

            analysis = json.loads(response.choices[0].message.content)
            return {'agent': 'data_analyst', 'analysis': analysis}
        except Exception as e:
            return {'agent': 'data_analyst', 'error': str(e)}

    def synthesis_agent(self, all_inputs: Dict) -> str:
        synthesis_prompt = f"""You are a synthesis specialist. Integrate all information into coherent insights.

Inputs from multiple agents:
{json.dumps(all_inputs, indent=2)[:40000]}

Create a synthesized narrative that:
1. Integrates all perspectives
2. Resolves contradictions
3. Highlights consensus and disagreements
4. Provides nuanced conclusions

Write a comprehensive synthesis (5000+ words)."""

        try:
            body = json.dumps({
                "anthropic_version": "bedrock-2023-05-31",
                "max_tokens": 200000,
                "messages": [{"role": "user", "content": synthesis_prompt}],
                "temperature": 0.6
            })

            response = self.bedrock.invoke_model(
                modelId="anthropic.claude-sonnet-4-5-v2:0",
                body=body
            )

            response_body = json.loads(response['body'].read())
            synthesis = response_body['content'][0]['text']

            return synthesis
        except Exception as e:
            return f"Synthesis error: {str(e)}"

    def coordinate_research(self, query: str, plan: Dict) -> Dict:
        librarian_results = []

        with ThreadPoolExecutor(max_workers=10) as executor:
            futures = []

            for strategy in plan.get('search_strategies', [])[:5]:
                search_query = strategy.get('strategy', query)
                futures.append(executor.submit(self.librarian_agent, search_query, {}))

            for future in as_completed(futures):
                result = future.result()
                librarian_results.extend(result.get('results', []))

        all_sources = []
        seen_urls = set()
        for item in librarian_results:
            if item['url'] not in seen_urls:
                seen_urls.add(item['url'])
                all_sources.append(item)

        analyst_result = self.data_analyst_agent(all_sources[:100])

        synthesis = self.synthesis_agent({
            'query': query,
            'plan': plan,
            'sources': all_sources[:200],
            'analyst_insights': analyst_result
        })

        return {
            'sources': all_sources,
            'analysis': analyst_result,
            'synthesis': synthesis,
            'metadata': {
                'total_sources': len(all_sources),
                'unique_urls': len(seen_urls)
            }
        }

