            'critiques': [],
            'iterations': [],
            'feedback_scores': []
        }

    def generate_session_id(self, query: str) -> str:
        timestamp = str(time.time())
        return hashlib.sha256(f"{query}{timestamp}".encode()).hexdigest()[:16]

    def update_state(self, **kwargs):
        with self.state_lock:
            for key, value in kwargs.items():
                self.research_state[key] = value
            self._persist_state()
            self._broadcast_state()

    def _persist_state(self):
        session_id = self.research_state.get('session_id')
        if session_id:
            state_json = json.dumps(self.research_state, default=str)

            for redis_client in [self.redis_dragonfly_1, self.redis_dragonfly_2, self.redis_dragonfly_3]:
                try:
                    redis_client.setex(f"session:{session_id}", 7200, state_json)
                except:
                    pass

    def _broadcast_state(self):
        session_id = self.research_state.get('session_id')
        if session_id:
            try:
                self.redis_upstash.publish(f"research_updates:{session_id}", json.dumps(self.research_state, default=str))
            except:
                pass

    def get_state(self, session_id: str) -> Dict:
        for redis_client in [self.redis_dragonfly_1, self.redis_dragonfly_2, self.redis_dragonfly_3]:
            try:
                state = redis_client.get(f"session:{session_id}")
                if state:
                    return json.loads(state)
            except:
                continue
        return {}

    def analyze_with_thinking_models(self, query: str, recalled_context: List[Dict]) -> Dict:
        self.update_state(
            current_action='Deep cognitive analysis with multiple thinking models',
            current_phase='Initial Analysis',
            progress=3
        )

        context_text = "\n".join([f"Memory {i+1}: {item['content']}" for i, item in enumerate(recalled_context[:15])])

        analysis_prompt = f"""You are conducting deep cognitive analysis of a research query.

Query: {query}

Recalled context from previous research:
{context_text}

Perform multi-dimensional analysis:
1. Semantic decomposition: Break down the query into fundamental concepts
2. Causal reasoning: Identify cause-effect relationships to explore
3. Temporal analysis: Historical context and future projections
4. Stakeholder mapping: Who is affected and how
5. Controversy detection: Identify areas of debate or disagreement
6. Knowledge gaps: What is unknown or uncertain
7. Cross-domain connections: Related fields or analogies

Return comprehensive analysis as JSON with all dimensions."""

        analyses = {}

        def analyze_qwen_thinking():
            try:
                response = self.cerebras.chat.completions.create(
                    model="qwen-3-235b-a22b-thinking-2507",
                    messages=[{"role": "user", "content": analysis_prompt}],
                    max_tokens=32768,
                    temperature=0.85
                )
                return {'model': 'qwen-thinking', 'analysis': response.choices[0].message.content}
            except Exception as e:
                return {'model': 'qwen-thinking', 'error': str(e)}

        def analyze_gpt_oss():
            try:
                response = self.cerebras.chat.completions.create(
                    model="gpt-oss-120b",
                    messages=[{"role": "user", "content": analysis_prompt}],
                    max_tokens=32768,
                    temperature=0.8
                )
                return {'model': 'gpt-oss-120b', 'analysis': response.choices[0].message.content}
            except Exception as e:
                return {'model': 'gpt-oss-120b', 'error': str(e)}

        def analyze_grok():
            try:
                response = self.xai_client.chat.completions.create(
                    model="grok-4-fast",
                    messages=[{"role": "user", "content": analysis_prompt}],
                    max_tokens=32768,
                    temperature=0.8
                )
                return {'model': 'grok-4-fast', 'analysis': response.choices[0].message.content}
            except Exception as e:
                return {'model': 'grok-4-fast', 'error': str(e)}

        with ThreadPoolExecutor(max_workers=3) as executor:
