        }

    def dynamic_search_execution(self, plan: Dict, iteration: int) -> Dict:
        self.update_state(
            current_action=f'Executing adaptive search strategies (iteration {iteration})',
            current_phase='Search Execution',
            progress=10 + (iteration * 8)
        )

        strategies = plan.get('search_strategies', [])
        strategies.sort(key=lambda x: x.get('priority', 0), reverse=True)

        all_results = []
        strategy_performance = []

        with ThreadPoolExecutor(max_workers=10) as executor:
            futures = []

            for strategy in strategies[:8]:
                search_query = strategy.get('strategy', '')

                for search_type in ['neural', 'keyword', 'auto']:
                    futures.append(executor.submit(
                        self._execute_single_search,
                        search_query,
                        search_type,
                        strategy
                    ))

            for future in as_completed(futures):
                result = future.result()
                all_results.extend(result['results'])
                strategy_performance.append(result['performance'])

        unique_sources = {}
        for result in all_results:
            url = result.get('url', '')
            if url and url not in unique_sources:
                unique_sources[url] = result

        return {
            'sources': list(unique_sources.values()),
            'performance': strategy_performance,
            'total_found': len(unique_sources)
        }

    def _execute_single_search(self, query: str, search_type: str, strategy: Dict) -> Dict:
        start_time = time.time()

        try:
            result = self.exa.search_and_contents(
                query=query,
                type=search_type,
                num_results=50,
                text=True,
                highlights=True
            )

            sources = [{
                'url': r.url,
                'title': getattr(r, 'title', ''),
                'text': getattr(r, 'text', ''),
                'highlights': getattr(r, 'highlights', []),
                'published_date': getattr(r, 'published_date', None),
                'author': getattr(r, 'author', None),
                'search_type': search_type,
                'strategy': strategy.get('strategy', '')
            } for r in result.results]

            elapsed = time.time() - start_time

            return {
                'results': sources,
                'performance': {
                    'query': query,
                    'type': search_type,
                    'count': len(sources),
                    'time': elapsed,
                    'strategy': strategy.get('strategy', '')
                }
            }

        except Exception as e:
            return {
                'results': [],
                'performance': {
                    'query': query,
                    'type': search_type,
                    'count': 0,
                    'time': time.time() - start_time,
                    'error': str(e)
                }
            }

    def deep_content_discovery(self, urls: List[str], iteration: int) -> List[Dict]:
        self.update_state(
            current_action=f'Deep content extraction and subpage discovery',
            current_phase='Content Discovery',
            progress=30 + (iteration * 5)
        )

        all_content = []

        def extract_with_subpages(url: str):
            try:
                result = self.exa.get_contents(
                    ids=[url],
                    text=True,
                    highlights=True,
                    summary=True
                )

                return [{
                    'url': r.url if hasattr(r, 'url') else url,
                    'text': getattr(r, 'text', ''),
                    'highlights': getattr(r, 'highlights', []),
                    'summary': getattr(r, 'summary', ''),
                    'type': 'subpage_discovery'
                } for r in result.results]

            except:
                return []

        def find_similar_content(url: str):
            try:
                result = self.exa.find_similar_and_contents(
                    url=url,
                    num_results=50,
                    text=True,
                    highlights=True,
                    exclude_source_domain=True
                )

                return [{
                    'url': r.url,
                    'title': getattr(r, 'title', ''),
                    'text': getattr(r, 'text', ''),
                    'highlights': getattr(r, 'highlights', []),
                    'type': 'similar_content'
                } for r in result.results]

            except:
                return []

        with ThreadPoolExecutor(max_workers=20) as executor:
            futures = []

            for url in urls[:40]:
                futures.append(executor.submit(extract_with_subpages, url))
                futures.append(executor.submit(find_similar_content, url))

            for future in as_completed(futures):
                content = future.result()
                all_content.extend(content)

        return all_content

