            response_body = json.loads(response['body'].read())
            report = response_body['content'][0]['text']

            enhancement_prompt = f"""Enhance and expand this report with even more depth, detail, and sophistication:

{report[:100000]}

Add:
More specific examples
Deeper analysis
Additional perspectives
Stronger evidence
More nuanced conclusions
Richer context

Return the enhanced report."""

            body2 = json.dumps({
                "anthropic_version": "bedrock-2023-05-31",
                "max_tokens": 4096,
                "messages": [{"role": "user", "content": enhancement_prompt}],
                "temperature": 0.6
            })

            response2 = self.bedrock.invoke_model(
                modelId="anthropic.claude-3-5-sonnet-20241022-v2:0",
                body=body2
            )

            response_body2 = json.loads(response2['body'].read())
            final_report = response_body2['content'][0]['text']

            return final_report

        except Exception as e:
            return f"Error generating report: {str(e)}\n\nPartial data:\n{syntheses_text[:20000]}"

    def autonomous_cognitive_research(self, query: str, max_duration_minutes: int = 90) -> Dict:
        session_id = self.generate_session_id(query)
        start_time = time.time()

        self.update_state(
            session_id=session_id,
            status='running',
            start_time=start_time,
            progress=0,
            current_action='Initializing cognitive research system',
            current_phase='Initialization'
        )

        try:
            recalled_memories = self.vector_memory.recall_similar(query, top_k=20)

            self.update_state(
                current_action=f'Recalled {len(recalled_memories)} relevant memories',
                progress=1
            )

            deep_analysis = self.analyze_with_thinking_models(query, recalled_memories)

            research_plan = self.planner.create_research_plan(query, recalled_memories)

            self.update_state(
                plan=research_plan,
                current_action='Strategic research plan created',
                progress=5
            )

            research_data = self.iterative_refinement_loop(query, research_plan, max_iterations=10)

            self.update_state(
                current_action='Performing critical review',
                current_phase='Critique',
                progress=90
            )

            initial_synthesis = research_data['syntheses'][-1] if research_data['syntheses'] else {}
            initial_synthesis_text = json.dumps(initial_synthesis)

            critique = self.critic.critique_findings(initial_synthesis_text, research_data['sources'])
            defense = self.critic.defend_or_revise(initial_synthesis_text, critique)

            critique_cycle = {
                'critique': critique,
                'defense': defense
            }

            self.update_state(
                critiques=[critique_cycle],
                progress=91
            )

            final_report = self.generate_comprehensive_report(query, research_data, critique_cycle)

            self.vector_memory.store_insight(
                final_report[:5000],
                {
                    'query': query,
                    'session_id': session_id,
                    'sources_count': len(research_data['sources']),
                    'type': 'research_report'
                }
            )

            end_time = time.time()
            duration = end_time - start_time

            self.update_state(
                status='complete',
                progress=100,
                current_action='Research complete',
                current_phase='Complete'
            )

            return {
                'session_id': session_id,
                'query': query,
                'report': final_report,
                'sources': research_data['sources'],
                'plan': research_plan,
                'iterations': research_data['iterations'],
                'critique_cycle': critique_cycle,
                'metadata': {
                    'duration_seconds': duration,
                    'total_sources': len(research_data['sources']),
                    'unique_urls': len(set(s['url'] for s in research_data['sources'] if s.get('url')))
                }
            }

        except Exception as e:
            self.update_state(
                status='error',
                current_action=f'Error: {str(e)}',
                progress=0
            )

            return {
                'session_id': session_id,
                'error': str(e),
                'query': query
            }

app = Flask(__name__)
CORS(app)

agent = CognitiveDeepSearchAgent()

@app.route('/api/research', methods=['POST'])
def start_research():
    data = request.get_json()
    query = data.get('query', '')

    if not query:
        return jsonify({'error': 'Query is required'}), 400

    def run_research():
        result = agent.autonomous_cognitive_research(query)
        return result

    executor = ThreadPoolExecutor(max_workers=1)
    future = executor.submit(run_research)

    session_id = agent.research_state.get('session_id')

    return jsonify({
        'session_id': session_id,
        'status': 'started',
        'message': 'Research initiated'
    })

@app.route('/api/status/<session_id>', methods=['GET'])
def get_status(session_id):
    state = agent.get_state(session_id)

    if not state:
        return jsonify({'error': 'Session not found'}), 404

    return jsonify(state)

@app.route('/api/stream/<session_id>', methods=['GET'])
def stream_updates(session_id):
    def generate():
        pubsub = agent.redis_upstash.pubsub()
        pubsub.subscribe(f"research_updates:{session_id}")

        for message in pubsub.listen():
            if message['type'] == 'message':
                yield f"data: {message['data'].decode('utf-8')}\n\n"

    return Response(generate(), mimetype='text/event-stream')

@app.route('/api/health', methods=['GET'])
def health_check():
    return jsonify({'status': 'healthy', 'timestamp': time.time()})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=False, threaded=True)
